  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    n = len(nodes)
    if n == 0:
        raise ValueError('Empty nodes list')

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        mrd = max(core_distance[u], core_distance[v], d)
        # canonicalize: smaller identifier first (string compare)
        if u > v:
            u, v = v, u
        edges.append((mrd, u, v))

    # Sort deterministically: primary by weight, then by u, then by v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find implementation
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    edges_used = 0

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            edges_used += 1
            if edges_used == n - 1:
                break

    if edges_used != n - 1:
        raise ValueError('Graph is disconnected; cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
